import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.118.0';

const app = document.querySelector('#app');
const status = (message, error = false) => {
  const node = document.querySelector('#auth-message');
  if (!node) return;
  node.textContent = message;
  node.classList.toggle('auth-error', error);
};
const escapeHTML = value => String(value ?? '').replace(/[&<>"']/g, char => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
}[char]));

let supabase;
let currentUser = null;
let initError = '';

function updateNav() {
  const actions = document.querySelector('.nav-actions');
  if (!actions) return;
  actions.innerHTML = `<button class="icon-button" id="search-toggle" aria-label="Search">⌕</button>
    <a class="login-link" href="${currentUser ? '#portal' : '#login'}">${currentUser ? 'My portal' : 'Log in'}</a>
    <a class="button button-dark button-sm" href="${currentUser ? '#portal' : '#signup'}">${currentUser ? 'Account ↗' : 'Start selling ↗'}</a>
    <button class="mobile-menu" id="mobile-menu" aria-label="Open menu">☰</button>`;
  document.querySelector('#search-toggle')?.addEventListener('click', () => { location.hash = 'explore'; });
  document.querySelector('#mobile-menu')?.addEventListener('click', () => document.querySelector('.main-nav')?.classList.toggle('open'));
}

function authPage(mode) {
  const signup = mode === 'signup';
  const title = signup ? 'Make a little room for good things.' : 'Good to see you again.';
  const intro = signup
    ? 'Join the home for independent creators and the people who love what they make.'
    : 'Log in to find your purchases, memberships and communities.';
  return `<div class="container page"><div class="form-shell">
    <span class="eyebrow">${signup ? 'Your next chapter' : 'Welcome back'}</span>
    <h1>${title}</h1><p>${intro}</p>
    <form id="auth-form" data-mode="${mode}" novalidate>
      ${signup ? '<label class="form-field"><span>Your name</span><input name="full_name" placeholder="e.g. Ananya Sharma" autocomplete="name" required></label>' : ''}
      <label class="form-field"><span>Email address</span><input name="email" type="email" placeholder="you@example.com" autocomplete="email" required></label>
      <label class="form-field"><span>Password</span><input name="password" type="password" placeholder="At least 8 characters" autocomplete="${signup ? 'new-password' : 'current-password'}" minlength="8" required></label>
      ${signup ? '' : '<div class="forgot-row"><a href="#forgot-password">Forgot password?</a></div>'}
      <button class="button button-dark" type="submit">${signup ? 'Create your account' : 'Log in'}&nbsp; ↗</button>
    </form>
    <p class="auth-message" id="auth-message" role="status">${initError ? escapeHTML(initError) : ''}</p>
    <div class="form-foot">${signup ? 'Already have an account? <a href="#login">Log in</a>' : 'New to Gully? <a href="#signup">Create an account</a>'}</div>
    <small class="auth-legal">By continuing, you agree to Gully’s Terms and Privacy Policy.</small>
  </div></div>`;
}

let activeProfileTab = 'created';
let activeCustomerTab = 'Customers';
const iconSvg = {home:'<svg viewBox="0 0 24 24"><path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-6H9v6H4a1 1 0 0 1-1-1z"/></svg>',messages:'<svg viewBox="0 0 24 24"><path d="M21 11.5a8.4 8.4 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.4 8.4 0 0 1-3.8-.9L3 21l1.9-5.7a8.4 8.4 0 0 1-.9-3.8A8.5 8.5 0 0 1 8.7 4a8.4 8.4 0 0 1 3.8-.9h.5a8.5 8.5 0 0 1 8 8z"/></svg>',partners:'<svg viewBox="0 0 24 24"><path d="M16 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2M10 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8zm7-7.8a4 4 0 0 1 0 7.6M20 21v-2a4 4 0 0 0-3-3.9"/></svg>',affiliates:'<svg viewBox="0 0 24 24"><circle cx="6" cy="5" r="3"/><circle cx="18" cy="19" r="3"/><circle cx="6" cy="19" r="3"/><path d="m8.7 6.5 6.6 11m0-11L8.7 17.5"/></svg>',workforce:'<svg viewBox="0 0 24 24"><rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V5a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M3 12h18m-11 0v2h4v-2"/></svg>',communities:'<svg viewBox="0 0 24 24"><rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/></svg>',settings:'<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .3 1.9l.1.1-1.7 2.9-.2-.1a1.7 1.7 0 0 0-1.9.3l-.1.1h-3.4l-.1-.2a1.7 1.7 0 0 0-1.6-1.1 1.7 1.7 0 0 0-.9.3l-.2.1L6.8 17l.1-.2a1.7 1.7 0 0 0-.3-1.9l-.1-.1v-3.4l.2-.1a1.7 1.7 0 0 0 1.1-1.6 1.7 1.7 0 0 0-.3-.9l-.1-.2 1.7-2.9.2.1a1.7 1.7 0 0 0 1.9-.3l.1-.1h3.4l.1.2a1.7 1.7 0 0 0 1.6 1.1 1.7 1.7 0 0 0 .9-.3l.2-.1 2.9 1.7-.1.2a1.7 1.7 0 0 0 .3 1.9l.1.1v3.4z"/></svg>'};
const portalLinks = [['home','Home'],['messages','Messages'],['partners','Partners'],['affiliates','Affiliates'],['workforce','Workforce'],['communities','Communities']];
function displayName() { return currentUser?.user_metadata?.full_name || currentUser?.email?.split('@')[0] || 'Creator'; }
function initialsFor(value) { return String(value || 'G').trim().split(/\s+/).slice(0,2).map(x => x[0]).join('').toUpperCase(); }
function portalShell(content, active='profile') {
  const name=displayName(), business=getBusiness();
  return `<div class="portal-app"><header class="portal-topbar"><a class="portal-brand" href="#portal"><span class="brand-mark">G</span> Gully</a><form class="portal-search" id="portal-search-form"><span class="portal-search-icon"><svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></svg></span><input name="query" placeholder="Search Gully" aria-label="Search Gully"><kbd>Ctrl K</kbd></form><div class="portal-top-actions"><button class="portal-icon-button" data-notifications aria-label="Notifications"><svg viewBox="0 0 24 24"><path d="M18 9a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg></button><button class="portal-account-button" data-menu-toggle aria-expanded="false"><span class="portal-avatar">${escapeHTML(initialsFor(name))}</span><span class="account-name">${escapeHTML(name)}</span><span aria-hidden="true">v</span></button><div class="portal-account-menu" id="portal-account-menu" hidden><div class="account-menu-head"><span class="portal-avatar">${escapeHTML(initialsFor(name))}</span><span><b>${escapeHTML(name)}</b><small>${escapeHTML(currentUser?.email||'')}</small></span></div><a href="#profile">View profile</a><a href="#resolution">Resolution center</a><a href="#orders">Orders</a><a href="#settings">Settings</a><a href="#help">Help and support</a><a href="#language">Language</a><a href="#legal">Legal</a><button data-signout>Sign out</button><div class="theme-picks"><button data-theme="dark">Dark</button><button data-theme="light">Light</button></div></div></div></header><div class="portal-layout"><aside class="portal-sidebar"><div class="portal-workspace-switch"><button class="workspace-selected">U</button>${business?`<a class="workspace-business" href="#business/home" title="Open ${escapeHTML(business.name)}">${escapeHTML(initialsFor(business.name))}</a>`:''}${business?`<button class="workspace-add" data-business-notice="Multiple business workspaces are coming soon." aria-label="Add business">+</button>`:`<a href="#create-business" aria-label="Create business">+</a>`}</div><span class="sidebar-label">Personal</span><nav class="portal-nav">${portalLinks.map(([route,label])=>`<a class="portal-nav-link ${active===route?'active':''}" href="#${route}"><span>${iconSvg[route]}</span>${label}</a>`).join('')}</nav><div class="portal-sidebar-bottom"><a class="portal-nav-link ${active==='settings'?'active':''}" href="#settings"><span>${iconSvg.settings}</span>Settings</a></div></aside><main class="portal-main">${content}</main></div></div>`;
}
function emptyPortal(icon,title,copy,link='explore',label='Explore Gully') { return `<div class="portal-empty-state"><span>${icon}</span><b>${title}</b><p>${copy}</p><a class="button button-primary" href="#${link}">${label} &rarr;</a></div>`; }
function profileContent() {
 const meta=currentUser?.user_metadata||{},name=displayName(),joined=currentUser?.created_at?new Date(currentUser.created_at).toLocaleDateString('en-IN',{month:'short',year:'numeric'}):'?',created=meta.creator_business;
 return `<div class="profile-page-heading"><span class="portal-kicker">PERSONAL PROFILE</span></div><section class="profile-card"><div class="profile-cover" style="background:${escapeHTML(meta.cover_color||'#252624')}"></div><div class="profile-body"><div class="profile-identity"><div class="profile-avatar-wrap"><span class="profile-avatar">${escapeHTML(initialsFor(name))}</span><i class="online-dot"></i></div><h1>${escapeHTML(name)}</h1><div class="profile-handle">@${escapeHTML(meta.username||currentUser?.email?.split('@')[0]||'creator')}</div><p class="profile-details">${meta.location?`${escapeHTML(meta.location)} | `:''}Joined ${escapeHTML(joined)}</p><div class="profile-followers"><b>0 Followers</b><b>0 Following</b></div>${meta.bio?`<p class="profile-bio">${escapeHTML(meta.bio)}</p>`:''}<div class="profile-actions"><button class="portal-action" data-edit-profile>Edit profile</button><a class="portal-action" href="#orders">Manage orders</a></div></div><div class="profile-tabs"><button class="${activeProfileTab==='created'?'selected':''}" data-profile-tab="created">Created</button><button class="${activeProfileTab==='joined'?'selected':''}" data-profile-tab="joined">Joined</button></div><div class="profile-tab-content">${activeProfileTab==='created'?(created?`<article class="business-card"><span class="business-avatar">${escapeHTML(initialsFor(created.name))}</span><div><b>${escapeHTML(created.name)}</b><p>@${escapeHTML(created.handle)} | ${escapeHTML(created.category)} | ${escapeHTML(created.status||'Setup')}</p></div><a class="text-link" href="#business/home">Open business &rarr;</a></article>`:emptyPortal('+ ','No businesses created','Start a creator page to sell digital products, memberships and community access.','create-business','Create a business')):emptyPortal('+ ','No communities joined yet','Communities and memberships you join will appear here.','communities','Explore communities')}</div></div></section>`;
}
function portalSubpage(route) {
 const pages={home:['Your Gully','Pick up where you left off.'],orders:['Orders','Your purchases and receipts, all in one place.'],messages:['Messages','Your conversations with creators and communities.'],partners:['Partners','Creator partnerships you are part of.'],affiliates:['Affiliates','Track your referrals and rewards.'],workforce:['Workforce','Teams and creator workspaces you can access.'],communities:['Communities','Your memberships and private community access.'],resolution:['Resolution center','Get help with an order or membership.'],help:['Help and support','Find answers or get in touch with Gully support.'],language:['Language','Choose the language for your portal.'],legal:['Legal','Policies and account information.']};
 if(route==='profile') return profileContent();
 if(route==='home') return `<div class="portal-page-heading"><span class="portal-kicker">PERSONAL</span><h1>Your Gully</h1><p>Your products, memberships and creator activity live here.</p></div><div class="help-cards"><article class="portal-panel help-card"><span>O</span><b>Orders</b><p>Purchased products and receipts.</p><a class="text-link" href="#orders">Manage orders &rarr;</a></article><article class="portal-panel help-card"><span>C</span><b>Communities</b><p>Memberships and private community access.</p><a class="text-link" href="#communities">View communities &rarr;</a></article><article class="portal-panel help-card"><span>+</span><b>Create a business</b><p>Build your creator storefront on Gully.</p><a class="text-link" href="#create-business">Get started &rarr;</a></article></div>`;
 if(route==='settings') return `<div class="portal-page-heading"><span class="portal-kicker">ACCOUNT</span><h1>Settings</h1><p>Manage your account and portal preferences.</p></div><section class="settings-list"><div class="settings-row"><div><b>Profile details</b><p>Update your name, username, location and bio.</p></div><button class="portal-action" data-edit-profile>Edit profile</button></div><div class="settings-row"><div><b>Appearance</b><p>Choose how Gully looks on this device.</p></div><div class="appearance-buttons"><button data-theme="dark">Dark</button><button data-theme="light">Light</button></div></div><div class="settings-row"><div><b>Email</b><p>${escapeHTML(currentUser?.email||'')}</p></div><a class="text-link" href="#help">Get help</a></div><div class="settings-row"><div><b>Sign out</b><p>End this session on this device.</p></div><button class="portal-action" data-signout>Sign out</button></div></section>`;
 if(route==='create-business') return `<div class="portal-page-heading"><span class="portal-kicker">CREATOR TOOLS</span><h1>Create your business</h1><p>Set up your creator storefront. You can add products and plans next.</p></div><section class="portal-panel business-form"><form id="business-form"><label class="form-field"><span>Business name</span><input name="business_name" required maxlength="80" placeholder="e.g. The Design Club"></label><label class="form-field"><span>Page handle</span><div class="handle-input"><span>gully.in/</span><input name="handle" required pattern="[a-z0-9-]{3,30}" placeholder="your-club"></div></label><label class="form-field"><span>Category</span><select name="category"><option>Courses</option><option>Community</option><option>Fitness</option><option>Finance</option><option>Design</option><option>Other</option></select></label><label class="form-field"><span>Short description</span><textarea name="description" rows="3" maxlength="240" placeholder="What will members get?"></textarea></label><p class="draft-note">Create your business workspace now. Add products and a website next; payments and member access will come when checkout is connected.</p><button class="button button-primary" type="submit">Create business workspace &rarr;</button><p class="auth-message" id="auth-message" role="status"></p></form></section>`;
 if(route==='language') return `<div class="portal-page-heading"><span class="portal-kicker">PREFERENCES</span><h1>Language</h1></div><section class="portal-panel language-panel"><p>Gully is currently available in English. More Indian languages are on the way.</p><button class="portal-action" disabled>English | Current</button></section>`;
 if(route==='legal') return `<div class="portal-page-heading"><span class="portal-kicker">INFORMATION</span><h1>Legal</h1></div><section class="portal-panel"><p>Terms of service and privacy information will be available here before launch.</p></section>`;
 if(route==='help'||route==='resolution') return `<div class="portal-page-heading"><span class="portal-kicker">SUPPORT</span><h1>${pages[route][0]}</h1><p>${pages[route][1]}</p></div><div class="help-cards"><article class="portal-panel help-card"><span>O</span><b>Order help</b><p>Find assistance with a purchase or payment.</p><a class="text-link" href="#orders">View orders &rarr;</a></article><article class="portal-panel help-card"><span>M</span><b>Membership access</b><p>Get help accessing a community you joined.</p><a class="text-link" href="#communities">View communities &rarr;</a></article><article class="portal-panel help-card"><span>@</span><b>Contact support</b><p>Need a hand? Email our support team.</p><a class="text-link" href="mailto:support@gully.in">Email support &rarr;</a></article></div>`;
 const [title,copy]=pages[route]||pages.home;
 return `<div class="portal-page-heading"><span class="portal-kicker">PERSONAL</span><h1>${title}</h1><p>${copy}</p></div><section class="portal-panel">${emptyPortal(route==='orders'?'#':'+ ',route==='orders'?'No orders yet':'Nothing here yet',route==='orders'?'Your digital products and receipts will appear here after checkout.':'This area will show your activity as Gully adds creator features.','explore',route==='orders'?'Explore products':'Explore Gully')}</section>`;
}
const businessRoutes=['business/home','business/analytics','business/products','business/product-new','business/payments','business/customers','business/websites','business/ads','business/workforce','business/affiliates','business/cards','business/support','business/more','business/developer','business/settings'];
const bizSections=[['', [['home','Home'],['analytics','Analytics'],['products','Products'],['payments','Payments'],['customers','Customers'],['websites','Websites']]],['Grow',[['ads','Ads'],['workforce','Workforce'],['affiliates','Affiliates']]],['Operations',[['cards','Cards'],['support','Support'],['more','More']]]];
const bizLabel={home:'Home',analytics:'Analytics',products:'Products','product-new':'New product',payments:'Payments',customers:'Customers',websites:'Websites',ads:'Ads',workforce:'Workforce',affiliates:'Affiliates',cards:'Cards',support:'Support',more:'More',developer:'Developer',settings:'Settings'};
function getBusiness(){const b=currentUser?.user_metadata?.creator_business;return b&&typeof b==='object'&&!Array.isArray(b)?b:null;}
function businessShell(content,active,business){
 const name=business.name||'Your business';
 return `<div class="portal-app business-app"><header class="portal-topbar"><a class="portal-brand" href="#business/home"><span class="brand-mark">G</span> Gully</a><form class="portal-search" id="portal-search-form"><span class="portal-search-icon"><svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></svg></span><input name="query" placeholder="Search ${escapeHTML(name)}" aria-label="Search business"><kbd>Ctrl K</kbd></form><div class="portal-top-actions"><button class="portal-icon-button" data-notifications aria-label="Notifications"><svg viewBox="0 0 24 24"><path d="M18 9a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg></button><button class="portal-account-button" data-menu-toggle aria-expanded="false"><span class="portal-avatar">${escapeHTML(initialsFor(name))}</span><span class="account-name">${escapeHTML(displayName())}</span><span>v</span></button><div class="portal-account-menu" id="portal-account-menu" hidden><div class="account-menu-head"><span class="portal-avatar">${escapeHTML(initialsFor(name))}</span><span><b>${escapeHTML(name)}</b><small>${escapeHTML(currentUser?.email||'')}</small></span></div><a href="#portal">Personal portal</a><a href="#business/settings">Business settings</a><a href="#help">Help and support</a><button data-signout>Sign out</button><div class="theme-picks"><button data-theme="dark">Dark</button><button data-theme="light">Light</button></div></div></div></header><div class="portal-layout"><aside class="portal-sidebar business-sidebar"><div class="business-switcher"><a class="workspace-personal" href="#portal" title="Personal portal">${escapeHTML(initialsFor(displayName()))}</a><button class="workspace-selected business-switch-button" title="Current business">${escapeHTML(initialsFor(name))}</button><button class="workspace-add" data-business-notice="Multiple business workspaces are coming soon." aria-label="Add another business">+</button></div><div class="business-side-title">${escapeHTML(name)}<span>${escapeHTML(business.status==='draft'?'Setup':'Business')}</span></div><nav class="business-nav">${bizSections.map(([group,items])=>`${group?`<span class="biz-section-label">${group}</span>`:''}${items.map(([key,label])=>`<a class="portal-nav-link ${active===key?'active':''}" href="#business/${key}"><span class="biz-icon">${({home:'H',analytics:'A',products:'P',payments:'$',customers:'C',websites:'W',ads:'A',workforce:'T',affiliates:'F',cards:'C',support:'S',more:'...'})[key]||'G'}</span>${label}${key==='workforce'?'<small class="biz-badge">Beta</small>':''}</a>`).join('')}`).join('')}<div class="business-more-links" id="business-more-links" hidden><a href="#business/developer">Developer</a><a href="#business/settings">Settings</a></div></nav><div class="business-side-bottom"><a class="portal-nav-link ${active==='developer'?'active':''}" href="#business/developer"><span class="biz-icon">&lt;/&gt;</span>Developer</a><a class="portal-nav-link ${active==='settings'?'active':''}" href="#business/settings"><span>${iconSvg.settings}</span>Settings</a></div></aside><main class="portal-main business-main">${content}</main></div></div>`;
}
function businessHeading(kicker,title,copy='',action=''){return `<div class="portal-page-heading business-heading"><div><span class="portal-kicker">${kicker}</span><h1>${title}</h1>${copy?`<p>${copy}</p>`:''}</div>${action}</div>`;}
function businessHome(b){
 const products=Array.isArray(b.products)?b.products.filter(p=>p&&typeof p==='object'):[];
 return `<div class="business-dashboard"><section class="business-overview"><div class="balance-overview"><span class="business-balance-label">Total balance | ${escapeHTML(b.name)}</span><strong>&#8377;0.00</strong><svg class="balance-chart" viewBox="0 0 720 190" preserveAspectRatio="none" aria-label="No sales yet"><defs><linearGradient id="balance-fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#c5e85b" stop-opacity=".14"/><stop offset="1" stop-color="#c5e85b" stop-opacity="0"/></linearGradient></defs><path d="M0 125 L35 112 L68 117 L99 101 L130 105 L162 91 L195 99 L225 83 L258 94 L290 78 L322 87 L353 70 L388 76 L420 61 L453 72 L485 55 L518 63 L550 43 L582 54 L615 36 L647 44 L680 25 L720 34 L720 190 L0 190Z" fill="url(#balance-fill)"/><path d="M0 125 L35 112 L68 117 L99 101 L130 105 L162 91 L195 99 L225 83 L258 94 L290 78 L322 87 L353 70 L388 76 L420 61 L453 72 L485 55 L518 63 L550 43 L582 54 L615 36 L647 44 L680 25 L720 34" fill="none" stroke="#8f9b68" stroke-width="2"/><path d="M0 180H720" stroke="#30312e" stroke-dasharray="2 5"/></svg><div class="business-balance-caption">Sales activity will appear here when you publish and sell.</div></div><div class="business-overview-side"><article class="business-widget website-widget"><h2><a href="#business/websites">Websites <span>&gt;</span></a></h2>${b.website?`<div class="website-connected"><span class="website-globe">W</span><div><b>${escapeHTML(b.website)}</b><p>Storefront link saved</p><a href="#business/websites">Manage website</a></div></div>`:`<div class="website-empty"><div class="website-globe">G</div><div><b>No website yet</b><p>Create or add your storefront link to share products with customers.</p><a href="#business/websites">+ Add a website</a></div></div>`}</article><article class="business-widget balance-widget"><h2>Balances</h2><a href="#business/payments"><span class="currency-mark">INR</span><b>Indian Rupee</b><strong>&#8377;0.00</strong><span>&gt;</span></a></article></div></section><div class="business-money-actions"><button data-money-action="Deposit"><span class="money-action-icon">&darr;</span> Deposit</button><button data-money-action="Accept"><span class="money-action-icon">+</span> Accept</button><button data-money-action="Send"><span class="money-action-icon">&rarr;</span> Send</button></div><section class="business-insight"><div><span class="insight-mark">G</span><b>${escapeHTML(b.name)} can grow with Gully Insights.</b><span class="insight-copy">Get a clearer view of your creator business.</span></div><button class="insight-toggle ${localStorage.getItem('gully-insights')==='on'?'on':''}" data-business-insights aria-pressed="${localStorage.getItem('gully-insights')==='on'}"><span></span><b>${localStorage.getItem('gully-insights')==='on'?'On':'Turn on'}</b></button></section><div class="business-quick-grid"><a href="#business/products"><b>Products</b><span>${products.length} active</span><small>Manage your digital products and plans</small></a><a href="#business/analytics"><b>Analytics</b><span>View performance</span><small>Revenue and customer activity</small></a><a href="#business/customers"><b>Customers</b><span>0 customers</span><small>See your customer list</small></a></div></div>`;
}
function analyticsCard(title,value,sub='',options=''){return `<article class="analytics-metric-card" data-analytics-metric="${escapeHTML(title)}"><header><b>${title}</b>${options}</header><strong>${value}</strong>${sub?`<small>${sub}</small>`:''}<div class="mini-chart-empty">No data available</div><footer><span>Today <b>${value}</b></span><span>Yesterday <b>${value}</b></span></footer></article>`;}
