<section class="analytics-card analytics-gtv" data-analytics-widget="Gross transaction value"><header><div><b>Gross transaction value</b><strong>&#8377;0.00</strong><small>Today</small></div><select aria-label="Chart grouping"><option>Per period</option><option>Per day</option></select></header><div class="analytics-empty-chart"><span>No data available</span></div><footer><span>Today &#8377;0.00</span><span>Yesterday &#8377;0.00</span></footer></section>
