window.addEventListener('hashchange', renderAuthRoute);

try {
  const response = await fetch('/api/public-config', { cache: 'no-store' });
  const config = await response.json();
  if (!response.ok) throw new Error(config.error || 'Unable to load Supabase configuration.');
  supabase = createClient(config.url, config.anonKey, {
    auth: { persistSession: true, autoRefreshToken: true, detectSessionInUrl: true },
  });
  const { data, error } = await supabase.auth.getSession();
  if (error) throw error;
  currentUser = data.session?.user || null;
  supabase.auth.onAuthStateChange((event, session) => {
    currentUser = session?.user || null;
    updateNav();
    if (location.hash === '#portal') renderAuthRoute();
    if (event === 'SIGNED_IN' && ['#login', '#signup'].includes(location.hash)) location.hash = 'portal';
  });
  window.gullyAuth = { client: supabase, get user() { return currentUser; } };
  renderAuthRoute();
} catch (error) {
  initError = error?.message || 'Supabase could not be reached.';
  renderAuthRoute();
}
